"""OBSOLETE (7 Oct 2026): Experiment 3 (text generated by Claude Haiku 4.5) was removed from the paper; kept for the record, not run by run_all.sh.
Experiment 3, oracle model-X reference: exact conditional randomization test on n' rows using
M regenerations X' ~ p(X | Z) of the comment from the same model and prompt (M is called B in the
code and in the file names). The statistic is the residual correlation rho_hat with X' in place of
X (the sentiment score A' recomputed and cross-fitted on psi = E1 with the same folds; the
residuals of the summary side unchanged).

usage: python experiments/exp3_crt.py GEN_JSONL CRT_JSONL [--only compute,plots]
"""
from __future__ import annotations

import argparse
import json
import sys
import time
from pathlib import Path

import numpy as np
import pandas as pd
from scipy import stats
from sklearn.decomposition import PCA
from sklearn.linear_model import RidgeCV
from threadpoolctl import threadpool_limits

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from citext import plotting as P  # noqa: E402
from citext.estimators import crossfit_folds, fit_predict_crossfit, residual_correlation  # noqa: E402
from citext.llm_gen import crt_rows  # noqa: E402
from citext.paths import RESULTS_DIR  # noqa: E402
from citext.text_semi import E1_NAME, embed_texts  # noqa: E402
from exp3_llm import LABEL_SCORE, embeddings, load_rows  # noqa: E402

ALPHA = 0.05
REGS = ("hybrid", "krr")


def phase_compute(gen_path: Path, crt_path: Path):
    t0 = time.time()
    rows = load_rows(gen_path)
    idx_pos = {r["idx"]: i for i, r in enumerate(rows)}
    emb = embeddings(rows, gen_path.stem)
    s_all = np.array([LABEL_SCORE.get(r["X_label"], 0.0) for r in rows])
    draws = [json.loads(l) for l in crt_path.read_text().splitlines() if l.strip()]
    sel_rows = crt_rows(gen_path, 500)
    B = max(d["b"] for d in draws) + 1
    by_idx = {}
    for d in draws:
        by_idx.setdefault(d["idx"], {})[d["b"]] = d["X_prime"]
    sel = [r for r in sel_rows if len(by_idx.get(r["idx"], {})) == B and all(by_idx[r["idx"]][b] for b in range(B))]
    S = np.array([idx_pos[r["idx"]] for r in sel])
    others = np.setdiff1d(np.arange(len(rows)), S)
    n_p = len(S)
    print(f"{n_p} rows with all {B} draws; direction fitted on {len(others)} other rows", flush=True)

    # summaries: direction w fitted on rows outside the subsample only (exactness of the CRT)
    EX, EY0, EY1, EZ = emb[("E1", "X")], emb[("E1", "Y0")], emb[("E1", "Y1")], emb[("E1", "Z")]
    w = RidgeCV(alphas=np.logspace(-2, 4, 13)).fit(EX[others], s_all[others])
    pca = PCA(1, random_state=0).fit(EX[others])
    pcaY = PCA(1, random_state=0).fit(EY0[others])
    Xp_texts = [by_idx[r["idx"]][b] for r in sel for b in range(B)]
    EXp = embed_texts(Xp_texts, E1_NAME, cache_key=f"{crt_path.stem}_Xprime").reshape(n_p, B, -1)
    axes = {
        "sentiment": (w.predict(EX[S]), w.predict(EY0[S]), w.predict(EY1[S]), np.stack([w.predict(EXp[:, b]) for b in range(B)], 1)),
        "pc1": (pca.transform(EX[S])[:, 0], pcaY.transform(EY0[S])[:, 0], pcaY.transform(EY1[S])[:, 0],
                np.stack([pca.transform(EXp[:, b])[:, 0] for b in range(B)], 1)),
    }
    Psi = EZ[S]
    folds = crossfit_folds(n_p, 5, 0)
    recs, out = [], {}
    for axis_name, (A, B0, B1, Ap) in axes.items():
        for reg in REGS:
            with threadpool_limits(4):
                rA = A - fit_predict_crossfit(Psi, A, 5, 0, reg, folds)
                rB0 = B0 - fit_predict_crossfit(Psi, B0, 5, 0, reg, folds)
                rB1 = B1 - fit_predict_crossfit(Psi, B1, 5, 0, reg, folds)
                rAp = Ap - fit_predict_crossfit(Psi, Ap, 5, 0, reg, folds)   # multi-output: same fits for all b
            res = {}
            for hyp, rB in (("H0", rB0), ("H1", rB1)):
                rho_obs, se_obs = residual_correlation(rA, rB)
                rho_b = np.array([residual_correlation(rAp[:, b], rB)[0] for b in range(B)])
                p_crt = (1 + np.sum(np.abs(rho_b) >= abs(rho_obs))) / (B + 1)
                z = rho_obs / se_obs
                res[hyp] = {"rho_obs": float(rho_obs), "se_obs": float(se_obs), "z_embedded": float(z),
                            "p_embedded": float(2 * stats.norm.sf(abs(z))), "p_crt": float(p_crt),
                            "rho_null_mean": float(rho_b.mean()), "rho_null_sd": float(rho_b.std(ddof=1)), "B": int(B), "n": int(n_p)}
                for b in range(B):
                    recs.append({"axis": axis_name, "reg": reg, "hyp": hyp, "b": b, "rho_b": float(rho_b[b]), "rho_obs": float(rho_obs)})
                print(f"  {axis_name} {reg} {hyp}: rho_obs={rho_obs:.3f} (z={z:.1f}, p_emb={res[hyp]['p_embedded']:.2g}); "
                      f"CRT null mean={rho_b.mean():.3f} sd={rho_b.std(ddof=1):.3f}; p_crt={p_crt:.3f}", flush=True)
            out[f"{axis_name}_{reg}"] = res
    pd.DataFrame(recs).to_csv(RESULTS_DIR / "exp3_llm_crt_raw.csv", index=False)
    usage_file = crt_path.with_suffix(".usage.json")
    out["usage"] = json.loads(usage_file.read_text()) if usage_file.exists() else None
    out["n_rows"], out["B"] = int(n_p), int(B)
    (RESULTS_DIR / "exp3_llm_crt.json").write_text(json.dumps(out, indent=1))
    print(f"CRT computed in {(time.time()-t0)/60:.1f} min", flush=True)


def phase_plots():
    import matplotlib.pyplot as plt
    P.setup()
    d = pd.read_csv(RESULTS_DIR / "exp3_llm_crt_raw.csv")
    info = json.loads((RESULTS_DIR / "exp3_llm_crt.json").read_text())
    sel = d[(d.axis == "sentiment") & (d.reg == REGS[0])]
    fig, ax = plt.subplots(figsize=P.SINGLE)
    rng = np.random.default_rng(0)
    for y, hyp, lab in ((1, "H0", r"$H_0$"), (0, "H1", r"$H_1$")):
        a = sel[sel.hyp == hyp]
        jit = rng.uniform(-0.12, 0.12, size=len(a))
        ax.plot(a.rho_b, y + jit, linestyle="none", marker="o", color=P.CAT[0], markersize=4.5, alpha=0.9, zorder=3)
        obs = float(a.rho_obs.iloc[0])
        ax.plot([obs, obs], [y - 0.3, y + 0.3], color=P.CAT[1], linewidth=1.8, zorder=4)
        r = info[f"sentiment_{REGS[0]}"][hyp]
        ax.annotate(rf"$p_{{\mathrm{{CRT}}}}={r['p_crt']:.2f}$,  embedded $z={r['z_embedded']:.1f}$", (0.0, y + 0.36), fontsize=6.5, color=P.INK2,
                    ha="left", va="bottom")
    ax.set_yticks([0, 1])
    ax.set_yticklabels([r"$H_1$", r"$H_0$"])
    ax.set_ylim(-0.5, 1.75)
    ax.set_xlim(left=min(-0.02, sel.rho_b.min() - 0.02))
    ax.set_xlabel(r"residual correlation $\hat\rho$ (subsample $n'=%d$, $\psi=E_1$, kernel ridge)" % info["n_rows"])
    from matplotlib.lines import Line2D
    handles = [Line2D([], [], marker="o", color=P.CAT[0], linestyle="none", label=rf"CRT null draws $\hat\rho^{{(m)}}$, $M={info['B']}$"),
               Line2D([], [], color=P.CAT[1], linewidth=1.8, label=r"observed $\hat\rho$")]
    ax.legend(handles=handles, loc="upper right")
    ax.grid(axis="y", visible=False)
    P.savefig(fig, "exp3_llm_crt.pdf")
    print("plots written", flush=True)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("gen_path")
    ap.add_argument("crt_path")
    ap.add_argument("--only", default="compute,plots")
    args = ap.parse_args()
    phases = args.only.split(",")
    if "compute" in phases:
        phase_compute(Path(args.gen_path), Path(args.crt_path))
    if "plots" in phases:
        phase_plots()


if __name__ == "__main__":
    main()
